// Daily-rotating "legacy" figures — a calm, motivational banner (not gamification).
// Real public-domain/CC portraits (Wikimedia) + themed scene backdrops (Unsplash),
// spanning science, art & literature, philosophy, music, sports, business & invention,
// activism & politics, exploration, mathematics, and film & performing arts.

const WM = (path: string) => "https://upload.wikimedia.org/" + path;
const WP = (n: string) =>
  "https://commons.wikimedia.org/wiki/Special:FilePath/" + encodeURIComponent(n) + "?width=600";
const UN = (id: string, w = 1200) =>
  "https://images.unsplash.com/photo-" + id + "?auto=format&fit=crop&w=" + w + "&q=72";

/** Reusable themed scene backdrops, shared across figures in the same field. */
