type SceneKey = keyof typeof SCENES;

export interface Figure {
  name: string;
  years: string;
  emoji: string;
  portrait: string;
  scene: string;
  sceneImg: string;
  /** True when sceneImg is a Wikimedia photo of a real place (not a generic Unsplash
   * stock scene) — these should skip Next's image optimizer like the portrait does,
   * for the same Wikimedia-rate-limit reason (see RemoteImage's `unoptimized`). */
  scenePersonal: boolean;
  quote: string;
  legacy: string;
}

interface RawFigure {
  name: string;
  years: string;
  emoji: string;
  portrait: string;
  scene: SceneKey;
  /** A real photo of a place tied to this person's life (birthplace, workplace, a landmark
   * tied to their achievement). Preferred over the generic field `scene` when present. */
  place?: string;
  placeCaption?: string;
  quote: string;
  legacy: string;
}

