export const FIGURES: Figure[] = RAW.map((f) => ({
  name: f.name,
  years: f.years,
  emoji: f.emoji,
  portrait: f.portrait,
  scene: f.place ? f.placeCaption! : SCENES[f.scene].label,
  sceneImg: f.place || SCENES[f.scene].img,
  scenePersonal: Boolean(f.place),
  quote: f.quote,
  legacy: f.legacy,
}));

/** Deterministic daily index (UTC day count) so server and client agree on first render. */
export function dailyFigureIndex(epochMs: number): number {
  return Math.floor(epochMs / 86400000) % FIGURES.length;
}
